  const html = `<html><body><p>Rules:</p><pre><code>${code}</code></pre><div aria-hidden="true"><pre><code>   secret_code()</code></pre></div><div>one</div><div>   two   </div><div>three</div></body></html>`;
  const text = extractHtml(html);
